import math
        import random
        import time

        LANGUAGE_WRAPPER = 'In a math contest preparation, a committee has a problem bank with questions of difficulties $1, 2, \\dots, {N}$. They want to select a set of problems $S$ to form a new contest. The scoring system is unusual: for any two disjoint subsets of problems $A, B \\subseteq S$, their total scores must not be congruent modulo ${M}$. That is, $\\sum_{a \\in A} a \\not\\equiv \\sum_{b \\in B} b \\pmod{{M}}$. What is the largest possible total score for a valid set of problems $S$?'

        class _RNGShim:
    def __init__(self, seed: int):
        import random as _random
        self._seed = int(seed)
        self._r = _random.Random(self._seed)

    def random(self): return self._r.random()
    def uniform(self, a, b): return self._r.uniform(a, b)
    def randint(self, a, b): return self._r.randint(a, b)
    def randrange(self, *args): return self._r.randrange(*args)
    def choice(self, seq): return self._r.choice(seq)
    def choices(self, population, weights=None, cum_weights=None, k: int = 1):
        return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
    def sample(self, population, k: int): return self._r.sample(population, k)
    def shuffle(self, x):
        self._r.shuffle(x)
        return x
    def getrandbits(self, k: int): return self._r.getrandbits(k)

        import math

def _solve(N, M):
    k_max = int(math.log2(M))
    S = []
    P = {0}
    for i in range(N, 0, -1):
        if len(S) == k_max:
            break

        i_mod_M = i % M
        if i_mod_M == 0:
            continue

        is_forbidden = False

        # Check against differences and negatives of existing subset sums.
        # This is faster than nested loops in the main generator logic.
        forbidden_values = set()
        for s1 in P:
            forbidden_values.add((-s1 + M) % M)
            for s2 in P:
                forbidden_values.add((s1 - s2 + M) % M)

        if i_mod_M in forbidden_values:
            is_forbidden = True

        if not is_forbidden:
            S.append(i)
            new_sums = {(s + i) % M for s in P}
            P.update(new_sums)
    return S, P

def generator(rng):
    while True:
        M = rng.randint(40, 200)
        k_max = int(math.log2(M))
        if k_max < 4:
            continue

        N_min = max(k_max * 2, M // 4)
        N_max = max(N_min + 5, int(M * 0.75))
        if N_min >= N_max:
            continue
        N = rng.randint(N_min, N_max)

        # Call the solver logic to ensure generated parameters lead to a non-trivial solution.
        s, p_sums = _solve(N, M)
        if len(s) >= max(3, k_max - 2):
            return {'N': N, 'M': M}

